class Solution {
  private int[] parent;

  private int find(int x) {
    while (parent[x] != x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  public long maxAlternatingSum(int[] nums, int[][] swaps) {
    int n = nums.length;
    parent = new int[n];
    for (int i = 0; i < n; i++) parent[i] = i;
    for (int[] s : swaps) parent[find(s[0])] = find(s[1]);
    int[] size = new int[n], evens = new int[n];
    for (int i = 0; i < n; i++) {
      int r = find(i);
      size[r]++;
      if (i % 2 == 0) evens[r]++;
    }
    long[] order = new long[n];
    for (int i = 0; i < n; i++) order[i] = ((long) find(i) << 40) | nums[i];
    java.util.Arrays.sort(order);
    long total = 0;
    for (int i = 0; i < n; ) {
      long root = order[i] >> 40;
      int j = i;
      while (j < n && (order[j] >> 40) == root) j++;
      int e = evens[(int) root], len = j - i;
      // values are ascending: the largest e go to even indices
      for (int t = i; t < j; t++) {
        long v = order[t] & ((1L << 40) - 1);
        total += (t - i >= len - e) ? v : -v;
      }
      i = j;
    }
    return total;
  }
}
